"""Re-apply edits when a hand-added message is generated by the new generation, or is not in the new DBC
(spec section 14): the hand code of such a message is not re-applied, never two copies."""
import json
from pathlib import Path

from cogent_carry import carry_forward, hand_added, merge_without, owned_region, region_kind

HEAD = ("#define IL_RX_NUM_PERIODIC   {n}\n#define IL_RX_NUM_MESSAGES   {n}\n#define IL_RX_NUM_FRAMES     {n}\n"
        "{flags}")
FLAG = "#define ILSet_{s}_DataChanged()        (il_Rx_DataChanged_Flag[{at}] |= (CAN_UINT8) ({mask}))\n"


def il_par_h(n, flags, handles, signals, extra=""):
    text = HEAD.format(n=n, flags=flags)
    text += "".join("#define VNIM_%s_MESSAGE     %d\n" % (h, i) for i, h in enumerate(handles + ["IL_RX"]))
    text += "".join(FLAG.format(s=s, at=at, mask=mask) for s, at, mask in signals)
    return text + extra + "/* end */\n"


def enum(names):
    return "typedef enum\n{\n" + "".join("   VNIM_%s_MSGID,\n" % n for n in names) + "   NUM_VNIM_MESSAGES\n}VNIM_MSG;\n"


def folder(root, name, h, names, dbc=None):
    d = Path(root) / name
    d.mkdir()
    (d / "nw_il_par.h").write_text(h, encoding="latin-1")
    (d / "nw_vnim_app_signals_par.h").write_text(enum(names), encoding="latin-1")
    if dbc is not None:
        (d / "fifo_plan.json").write_text(json.dumps({"dbc_messages": dbc}), encoding="utf-8")
    return d


A, C, D = ("A_X", "0", "0x1"), ("C_Y", "0", "0x2"), ("D_W", "0", "0x4")
B = ("B_Z", "IL_MUX_MSG_OFFSET_ID + 0", "0x1")
BASE = il_par_h(2, "#define IL_NUM_OF_RX_DATA_CHANGED_FLAG   1\n", ["A", "C"], [A, C])
EDITED = il_par_h(3, "#define IL_NUM_OF_RX_DATA_CHANGED_FLAG   (1 + 1) \n#define IL_MUX_MSG_OFFSET_ID   0 \n",
                  ["A", "B", "C"], [A, C, B]) + "/* my note */\n"      # an edit away from the generated changes


def test_hand_added_messages_are_found():
    assert hand_added(BASE, EDITED) == ["B"]


def test_regions_of_a_generated_message_are_left_out():
    base = ["x = A_SIG;", "end"]
    edited = ["x = A_SIG;", "y = B_SIG1;", "z = B_SIG2;", "end", "keep = 1;"]
    out = merge_without(base, edited, lambda lines: all("B_" in l for l in lines))
    assert out == ["x = A_SIG;", "end", "keep = 1;"]


def test_inserted_construct_among_similar_ones_is_left_out_whole():
    def union(msg):
        return ["typedef union {", "   CAN_UINT8  msg_buffer[8];", "   %s_msgType %s;" % (msg, msg.lower()),
                "}%s_buf;" % msg, ""]
    base = union("BMS18_50") + union("BMS1_10")
    edited = union("BMS18_50") + union("BMS19_100") + union("BMS1_10")
    owned = {"BMS19_100"}
    assert merge_without(base, edited, lambda lines: region_kind(lines, owned, {"BMS18_50", "BMS1_10"})) == base


def test_owned_region_needs_an_owned_name_and_no_foreign_name():
    owned, foreign = {"BMS19_100", "BMS_CELLTEMP1", "IL_MUX_MSG_OFFSET_ID"}, {"BMS1_10", "BMS_SOC"}
    assert owned_region(["#define VNIM_BMS19_100_MESSAGE 15"], owned, foreign)
    assert owned_region(["CAN_UINT16 BMS19_100__CELLTEMP1;", "{", "}"], owned, foreign)
    assert owned_region(["   rValue = (CAN_UINT16)((CAN_UINT16)Rx_buffer.bms19_100.x);"], owned, foreign)
    assert not owned_region(["#define VNIM_BMS19_100_MESSAGE 15", "#define VNIM_BMS1_10_MESSAGE 16"], owned, foreign)
    assert not owned_region(["/* my note */"], owned, foreign)
    assert not owned_region(["#define ILSet_BMS_CELLTEMP10_DataChanged()"], {"BMS_CELLTEMP1"}, foreign)
    assert owned_region(["CAN_UINT16 IlRxGetBMS_CELLTEMP1(void);"], {"BMS_CELLTEMP1"}, foreign)


def test_generated_hand_added_message_is_kept_once(tmp_path):
    new = il_par_h(4, "#define IL_NUM_OF_RX_DATA_CHANGED_FLAG   (1 + 1) \n#define IL_MUX_MSG_OFFSET_ID   1 \n",
                   ["A", "B", "C", "D"], [A, C, D, B])
    base = folder(tmp_path, "base", BASE, ["A", "C"])
    edited = folder(tmp_path, "edited", EDITED, ["A", "B", "C"])
    newd = folder(tmp_path, "new", new, ["A", "B", "C", "D"], dbc=["A", "B", "C", "D"])
    results = carry_forward(base, edited, newd, tmp_path / "out")
    text = (tmp_path / "out" / "app.nos.arch3" / "src" / "nw_il_par.h").read_text(encoding="latin-1")
    assert text.count("#define ILSet_B_Z_DataChanged()") == 1
    assert "#define IL_RX_NUM_MESSAGES   4" in text and "#define IL_MUX_MSG_OFFSET_ID   1 " in text
    assert "(1 + 1)" in text and "/* my note */" in text
    il = next(r for r in results if r["file"] == "nw_il_par.h")
    assert not il["conflicts"] and not il["checks"]
    assert ("B", "now generated") in il["hand_added"]
    from cogent_carry import report
    assert "- B: CoGeNT generates it now; your hand code was not re-applied" in report(results, base, edited, newd, "out")


def test_hand_added_message_not_in_the_new_dbc_is_dropped(tmp_path):
    new = il_par_h(3, "#define IL_NUM_OF_RX_DATA_CHANGED_FLAG   1\n", ["A", "C", "D"], [A, C, D])
    base = folder(tmp_path, "base", BASE, ["A", "C"])
    edited = folder(tmp_path, "edited", EDITED, ["A", "B", "C"])
    newd = folder(tmp_path, "new", new, ["A", "C", "D"], dbc=["A", "C", "D"])
    results = carry_forward(base, edited, newd, tmp_path / "out")
    text = (tmp_path / "out" / "app.nos.arch3" / "src" / "nw_il_par.h").read_text(encoding="latin-1")
    assert "B_Z" not in text and "VNIM_B_MESSAGE" not in text and "IL_MUX_MSG_OFFSET_ID" not in text
    assert "#define IL_RX_NUM_MESSAGES   3" in text and "/* my note */" in text
    enum_text = (tmp_path / "out" / "app.vnim.arch3" / "nw_vnim_app_signals_par.h").read_text(encoding="latin-1")
    assert "VNIM_B_MSGID" not in enum_text
    il = next(r for r in results if r["file"] == "nw_il_par.h")
    assert not il["conflicts"] and not il["checks"]
    assert ("B", "not in the DBC") in il["hand_added"]


# ---- the real case (local only): 40024 workspace edits onto 41490 with BMS19_100/BMS20_100 generated -----
import os            # noqa: E402
import re            # noqa: E402
import shutil        # noqa: E402
import zipfile       # noqa: E402
from collections import Counter  # noqa: E402

import pytest        # noqa: E402

from support import CODE_FILES, ROOT, enable_indexed, latest_run  # noqa: E402

WS = Path(os.environ.get("COGENT_REFERENCE_WS", r"D:\networkgen\dc.app.scl.vehiclecomm"))
DBC_41490 = Path(r"D:\networkgen\DBC\DBC_V41490\S2XX_SMART_CORE_SVNID_41490_01_10_2026_Edited.dbc")
CFG_41490 = ROOT / "local_reports" / "DBC_41490" / "S2XX_41490_with_FIFO.cfg"
BASE_40024 = ROOT / "CODE_GEN" / "DBC_40024"
LOCAL = pytest.mark.skipif(not all(p.exists() for p in (WS, DBC_41490, CFG_41490, BASE_40024)),
                           reason="INCOMPLETE: workspace, 41490 DBC/configuration or CODE_GEN/DBC_40024 not available")
BMS = re.compile(r"BMS19_100|BMS20_100|BMS_CELLTEMP|BMS_CELLVOLTAGE|IL_MUX_MSG_OFFSET_ID")


def _generate_41490(home, dbc, enable, drop_additional=False):
    from cogent_generate import run_code_generation
    (home / "data").mkdir(parents=True)
    with zipfile.ZipFile(CFG_41490) as z:
        for n in z.namelist():
            if n.startswith("data/"):
                (home / n).write_bytes(z.read(n))
    if enable:
        enable_indexed(home, dbc, "SMART_CORE")
    if drop_additional:                          # as the generator asks when the DBC lacks them
        fifo = home / "data" / "CanFifoConfiguration.data"
        cfg = json.loads(fifo.read_text(encoding="utf-8"))
        cfg.pop("additional_rx_messages", None)
        fifo.write_text(json.dumps(cfg), encoding="utf-8")
    old = os.getcwd()
    os.chdir(home)
    try:
        run_code_generation(str(dbc), "SMART_CORE", "2000-01-01 00:00")
    finally:
        os.chdir(old)
    return latest_run(home)


def _bms(text):
    return Counter(re.sub(r"\s+", "", l) for l in text.replace("\r", "").split("\n") if BMS.search(l))


def _text(folder, name):
    from cogent_carry import generated_path
    return generated_path(folder, name).read_text(encoding="latin-1")


@LOCAL
def test_workspace_edits_onto_41490_with_generated_bms(tmp_path):
    new = _generate_41490(tmp_path / "home", DBC_41490, True)
    results = carry_forward(BASE_40024, WS, new, tmp_path / "out")
    for r in results:
        assert not r["conflicts"] and not r["checks"], (r["file"], r["conflicts"][:1], r["checks"])
    out = tmp_path / "out"
    for name in CODE_FILES:                       # the BMS code is exactly the generated one, once
        assert _bms(_text(out, name)) == _bms(_text(new, name)), name
    h, c, v = _text(out, "nw_il_par.h"), _text(out, "nw_il_par.c"), _text(out, "nw_vnim_app_signals_par.c")
    assert re.search(r"^#define IL_RX_NUM_MESSAGES\s+195\s*$", h, re.M)
    assert re.search(r"^#define IL_MUX_MSG_OFFSET_ID\s+163\s*$", h, re.M) and "(163 + 17)" in h
    assert c.count("void BMS19_100_PreCopy") == 1 and v.count("NM_MSG_MISSING(VNIM_BMS19_100_MSGID);") == 1
    assert "/* MCM_SLEEP */" in _text(out, "nw_nm_par.h")          # your NM transmit table is kept
    il = next(r for r in results if r["file"] == "nw_il_par.h")
    assert il["hand_added"] == [("BMS19_100", "now generated"), ("BMS20_100", "now generated")]


@LOCAL
def test_workspace_edits_onto_a_dbc_without_bms(tmp_path):
    text = DBC_41490.read_text(encoding="latin-1")
    for msg_id in ("1003", "1004"):                # drop the BO_ blocks of BMS19_100 / BMS20_100
        text = re.sub(r"\nBO_ %s .*?\n\n" % msg_id, "\n\n", text, flags=re.S)
    dbc = tmp_path / "no bms" / DBC_41490.name
    dbc.parent.mkdir()
    dbc.write_text(text, encoding="latin-1")
    new = _generate_41490(tmp_path / "home", dbc, False, drop_additional=True)
    results = carry_forward(BASE_40024, WS, new, tmp_path / "out")
    for r in results:
        assert not r["conflicts"] and not r["checks"], (r["file"], r["conflicts"][:1], r["checks"])
    for name in CODE_FILES:
        assert not _bms(_text(tmp_path / "out", name)), name
    il = next(r for r in results if r["file"] == "nw_il_par.h")
    assert il["hand_added"] == [("BMS19_100", "not in the DBC"), ("BMS20_100", "not in the DBC")]


def test_generated_and_re_applied_hand_added_messages_together(tmp_path):
    """B is generated now, E (still in the DBC, Rx enable off) keeps its hand code: E's flag in the
    multiplex area must stay."""
    F, G = ("F_U", "0", "0x4"), ("G_T", "0", "0x8")
    E = ("W_Q", "IL_MUX_MSG_OFFSET_ID + 0", "0x2")         # a signal name without the message name
    base = il_par_h(3, "#define IL_NUM_OF_RX_DATA_CHANGED_FLAG   1\n", ["A", "C", "F"], [A, C, F])
    edited = il_par_h(5, "#define IL_NUM_OF_RX_DATA_CHANGED_FLAG   (1 + 1) \n#define IL_MUX_MSG_OFFSET_ID   1 \n",
                      ["A", "B", "C", "E", "F"], [A, C, F, B, E]) + "/* my note */\n"
    new = il_par_h(5, "#define IL_NUM_OF_RX_DATA_CHANGED_FLAG   (1 + 1) \n#define IL_MUX_MSG_OFFSET_ID   1 \n",
                   ["A", "B", "C", "F", "G"], [A, C, F, G, B])     # G: new in the DBC, at the end
    based = folder(tmp_path, "base", base, ["A", "C", "F"])
    ed = folder(tmp_path, "edited", edited, ["A", "B", "C", "E", "F"])
    newd = folder(tmp_path, "new", new, ["A", "B", "C", "F", "G"], dbc=["A", "B", "C", "E", "F", "G"])
    results = carry_forward(based, ed, newd, tmp_path / "out")
    text = (tmp_path / "out" / "app.nos.arch3" / "src" / "nw_il_par.h").read_text(encoding="latin-1")
    il = next(r for r in results if r["file"] == "nw_il_par.h")
    assert ("B", "now generated") in il["hand_added"] and ("E", "re-applied") in il["hand_added"]
    assert text.count("#define ILSet_W_Q_DataChanged()") == 1 and text.count("#define ILSet_B_Z_DataChanged()") == 1
    assert "VNIM_E_MESSAGE" in text and "#define IL_RX_NUM_MESSAGES   6" in text and "/* my note */" in text
    # both sides append flags at the end of the list: you decide the order (one conflict, E's flag on your side)
    assert len(il["conflicts"]) == 1 and any("W_Q" in line for line in il["conflicts"][0][3])
